// AI Agent 출력 처리 개선
const items = $input.all();
let aiOutput = '';

// AI Agent 출력 찾기 (다양한 구조 대응)
for (const item of items) {
  if (item.json) {
    // AI Agent 출력 패턴들 확인
    if (item.json.output) {
      aiOutput = item.json.output;
      break;
    } else if (item.json.text) {
      aiOutput = item.json.text;
      break;
    } else if (typeof item.json === 'string') {
      aiOutput = item.json;
      break;
    } else if (item.json.response) {
      aiOutput = item.json.response;
      break;
    } else {
      // 객체의 값들 중 가장 긴 문자열 찾기 (AI 출력일 가능성 높음)
      for (const [key, value] of Object.entries(item.json)) {
        if (typeof value === 'string' && value.length > 100) {
          if (value.includes(':gear:') || value.includes('기사') || value.includes('뉴스')) {
            aiOutput = value;
            break;
          }
        }
      }
    }
  }
}

// 출력이 없을 경우 디버깅 정보 포함
if (!aiOutput) {
  console.log('AI Agent 출력 구조:', JSON.stringify(items, null, 2));
  aiOutput = `:warning: AI 요약 생성 중 문제가 발생했습니다.\n입력 구조를 확인해주세요.`;
}

// 현재 날짜 (한국 시간)
const today = new Date().toLocaleDateString('ko-KR', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: 'numeric', 
  day: 'numeric'
});

// 최종 슬랙 메시지 구성
const finalMessage = `:mega: 오늘의 AI 뉴스 요약 (${today})\n\n안녕하세요! IT 뉴스 전문 에디터입니다. 최신 RSS 피드 기사들을 슬랙에서 한눈에 보기 쉽게 요약해 정리했습니다.\n\n---\n\n${aiOutput}\n\n---\n\n자동화된 n8n 워크플로우로 생성됨`;

return [{
  json: {
    slack_message: finalMessage
  }
}];

// Aggregate된 데이터를 AI Agent가 이해할 수 있는 형태로 변환
const aggregatedData = $input.first().json;

// 각 필드의 배열을 개별 기사 객체로 재구성
const articles = [];
const articleCount = aggregatedData.제목 ? aggregatedData.제목.length : 0;

for (let i = 0; i < articleCount; i++) {
  articles.push({
    제목: aggregatedData.제목[i] || '',
    링크: aggregatedData.링크[i] || '',
    내용: aggregatedData.내용[i] || '',
    발행일: aggregatedData.발행일[i] || '',
    카테고리: Array.isArray(aggregatedData.카테고리[i]) ? aggregatedData.카테고리[i].join(', ') : (aggregatedData.카테고리[i] || 'IT/기술')
  });
}

// AI Agent에게 전달할 구조화된 텍스트 생성
let formattedText = `총 ${articles.length}개의 IT 뉴스 기사:\n\n`;

articles.forEach((article, index) => {
  formattedText += `[기사 ${index + 1}]\n`;
  formattedText += `제목: ${article.제목}\n`;
  formattedText += `링크: ${article.링크}\n`;
  formattedText += `발행일: ${article.발행일}\n`;
  formattedText += `카테고리: ${article.카테고리}\n`;
  formattedText += `내용: ${article.내용.substring(0, 500)}${article.내용.length > 500 ? '...' : ''}\n`;
  formattedText += `---\n\n`;
});

return {
  json: {
    formatted_articles: formattedText,
    article_count: articles.length,
    articles: articles
  }
};
